#ifndef TSFP_SURFACE_STATE_SHADER_H
#define TSFP_SURFACE_STATE_SHADER_H
/* Convert reconstructed (signed velocity, height) to the original feedback
 * texture contract. The final ripple shader samples height from ALPHA.
 * Red is scratch, regenerated by the first feedback pass. This is not the
 * final shaded texture; adapters provide vector types and target storage. */
#define TSFP_SURFACE_STATE_SHADER \
    TSFP_SURFACE_VEC4 " surface_state(" TSFP_SURFACE_VEC2 " state) {\n" \
    " return " TSFP_SURFACE_VEC4 "(0,state.x+0.5,state.y,state.y);\n}\n"
#endif
